import { test, expect } from '@playwright/test';

const searchbox = (page: import('@playwright/test').Page) =>
  page.getByRole('searchbox', { name: 'Search', exact: true });

test('REQ-3-1 scenario 1: a visitor searches the public repository and opens its overview', async ({
  page,
}) => {
  await page.goto('/');
  await searchbox(page).fill('acme-docs');
  await searchbox(page).press('Enter');

  await expect(page.getByRole('link', { name: 'acme-docs', exact: true })).toBeVisible();
  await expect(page.getByText('acme-demo/acme-docs', { exact: true })).toBeVisible();

  await page.getByRole('link', { name: 'acme-docs', exact: true }).click();
  await expect(page.getByRole('heading', { name: /acme-docs/ })).toBeVisible();
});

test('REQ-3-1 scenario 2: searching the private repository name exposes no result link', async ({
  page,
}) => {
  await page.goto('/');
  await searchbox(page).fill('secret-research');
  await searchbox(page).press('Enter');

  await expect(page).toHaveURL(/\/search\?/);
  await expect(page.getByRole('link', { name: 'secret-research', exact: true })).toHaveCount(0);
  await expect(page.getByText('secret-research', { exact: true })).toHaveCount(0);
});

test('REQ-3-1 scenario 3: an unmatched query shows the no-results message, also when repeated from home', async ({
