      const row = await tx.run(`INSERT INTO branches (repo_id, name, head_commit_id, created_at, updated_at) VALUES (?,?,NULL,?,?)`, [forkRepoId, branch.name, now, now]);
      branchMap.set(branch.id, row.lastID);
    }
    // copy files
    const files = await tx.all('SELECT * FROM repo_files WHERE repo_id = ?', [source.id]);
    for (const file of files) {
      const targetBranch = branchMap.get(file.branch_id);
      if (!targetBranch) continue;
      await tx.run(`INSERT INTO repo_files (repo_id, branch_id, path, content, updated_at) VALUES (?,?,?,?,?)`, [forkRepoId, targetBranch, file.path, file.content, now]);
    }
    // copy commits oldest first, remapping parents
    const commits = await tx.all('SELECT * FROM commits WHERE repo_id = ? ORDER BY id', [source.id]);
    const commitMap = new Map();
    for (const commit of commits) {
      const parent = commit.parent_commit_id ? commitMap.get(commit.parent_commit_id) ?? null : null;
      const row = await tx.run(`INSERT INTO commits (repo_id, sha, message, author_name, author_account_id, parent_commit_id, branch_name, created_at) VALUES (?,?,?,?,?,?,?,?)`,
