      commitMap.set(commit.id, row.lastID);
      const changed = await tx.all('SELECT * FROM commit_files WHERE commit_id = ?', [commit.id]);
      for (const file of changed) await tx.run(`INSERT INTO commit_files (commit_id, path, additions, deletions, change_type, diff) VALUES (?,?,?,?,?,?)`, [row.lastID, file.path, file.additions, file.deletions, file.change_type, file.diff]);
    }
    // heads
    for (const branch of branches) {
      if (!branch.head_commit_id) continue;
      const mapped = commitMap.get(branch.head_commit_id);
      if (mapped) await tx.run('UPDATE branches SET head_commit_id = ? WHERE repo_id = ? AND name = ?', [mapped, forkRepoId, branch.name]);
    }
    return forkRepoId;
  });
