import { expect, type Page } from '@playwright/test';

export function uniqueName(prefix: string): string {
  return `${prefix} ${Date.now().toString(36)}${Math.random().toString(36).slice(2, 7)}`;
}

export async function openHome(page: Page): Promise<void> {
  await page.goto('/');
  await expect(page.getByRole('heading', { name: 'Workbooks', exact: true })).toBeVisible();
}

// Opening a workbook the way a user does: from the home page by clicking its name.
export async function openWorkbook(page: Page, name: string): Promise<void> {
  await openHome(page);
  await page.getByRole('link', { name, exact: true }).first().click();
  await expect(page.getByRole('heading', { name, exact: true })).toBeVisible();
}

export async function createBlankWorkbook(page: Page): Promise<void> {
  await openHome(page);
  await page.getByRole('button', { name: 'New blank workbook', exact: true }).click();
  await page.getByRole('button', { name: 'Create', exact: true }).click();
  await expect(page.getByRole('tab', { name: 'Sheet1', exact: true })).toBeVisible();
}

export async function importCsv(page: Page, fileName: string, content: string): Promise<void> {
  await openHome(page);
  await page.getByRole('button', { name: 'Import CSV', exact: true }).click();
  await page.getByLabel('CSV file').setInputFiles({
    name: fileName,
    mimeType: 'text/csv',
    buffer: Buffer.from(content, 'utf8'),
  });
  await page.getByRole('button', { name: 'Confirm import', exact: true }).click();
}

export function cell(page: Page, address: string) {
  return page.getByRole('gridcell', { name: address, exact: true });
}
=== PLAN ===
# Online Spreadsheet Data Workspace - PLAN

## Stack and layout
- `backend/` Express 5 + sqlite3; serves `/api/*` and the built frontend (`frontend/dist`).
- `frontend/` Vite + React 19 + react-router-dom. Routes: `/` (home), `/workbooks/new` (creation page), `/workbooks/:id` (editor).
- No accounts/auth in this product (no requirement mentions them); every workbook is public and listed on the home page.

## Data model (SQLite, `backend/src/database/init_db.js`)
- `workbooks(id, name, created_at, updated_at, active_sheet_id)` - `updated_at` changes only on content/name changes, not on UI state (active sheet).
- `sheets(id, workbook_id, name, position, doc TEXT, updated_at)` - `doc` is the worksheet document as JSON:
  - `cells`: `{ "A1": "Region", "C1": "=A1+B1" }` raw text (a leading `=` means formula unless listed in `literals`)
  - `literals`: `{ "A1": true }` cells whose stored text is literal although it starts with `=` (CSV import)
  - `rows`, `cols`: current structure size (rendered area is `max(rows, used+1)`)
  - `validations`: `[{ id, type: "dropdown"|"number", range: {r1,c1,r2,c2}, options: [...], min, max }]`
  - `filter`: `null | { range:{r1,c1,r2,c2}, columnIndex, mode:"value"|"condition", value, values:[] }` (visibility only)
  - `pivot`: `null | { sourceSheetId, sourceRange, rowField, valueField, aggregation }` (in a pivot worksheet)
- The grid geometry (selection, active cell) is not persisted; the active worksheet is (`workbooks.active_sheet_id`).

## API (JSON; `Cache-Control: no-store`; errors `{ message }`)
- `GET /api/health`
- `GET /api/workbooks` -> `[{ id, name, updatedAt }]` (newest first)
- `POST /api/workbooks { name? }` -> creates a blank workbook containing only `Sheet1`
- `POST /api/workbooks/import { name, csvText }` -> parses CSV server side (400 `{message}` if invalid), creates workbook
- `GET /api/workbooks/:id` -> `{ id, name, updatedAt, activeSheetId, sheets: [{ id, name, position, doc }] }`
- `PATCH /api/workbooks/:id { name?, activeSheetId? }`
- `POST /api/workbooks/:id/sheets { name?, doc? }` -> add worksheet
- `PATCH /api/sheets/:id { name?, doc? }` -> rename worksheet / save its document
- `DELETE /api/sheets/:id` -> delete worksheet

Every change is saved immediately (whole document, `keepalive`), in arrival order thanks to the API queue in `app.js`.

## Seed (idempotent, on an empty database; `seed_db.js`)
- Workbook `Q3 Sales` (active worksheet `Sheet1`):
  - `Sheet1`: `A1:C4` = Region/Sales/Status, East/1200/Open, North/800/Closed, South/700/Open
  - `Sheet2`: `A1:B3` = Item/Qty, Pen/4, Ruler/2 (used by worksheet switching/rename/delete tests)
- Nothing else is seeded; every other object is created through the UI.

## Shared UI components (`frontend/src/components`)
- `Grid`: `role="grid"` named `Worksheet grid`, `aria-multiselectable="true"`; `columnheader` A.., `rowheader` 1..,
  `gridcell` with `aria-label="A1"` and `aria-selected`; drag selection, keyboard, context menus, inline editors.
- `SheetTabs`: `role="tablist"` with `role="tab"` per worksheet, active `aria-selected="true"`, button `Add worksheet`,
  per tab button `Worksheet options for <name>` opening a menu of `menuitem` buttons.
- `Toolbar`: undo/redo, `Export CSV`, `Data` menu and the area specific buttons.
- `FormulaBar`: `<textarea rows=1>` labelled `Formula bar`.
- `Menu` (`role="menu"` + `menuitem` buttons), `Dialog` (`role="dialog"` + heading), `ComboBox` (ARIA combobox + listbox/option),
  `NamePrompt` style inline forms.
- History: in-memory snapshot stack per worksheet document, cleared on reload (Undo/Redo disabled).

## Feature areas (build order)
1. **Base + REQ-1** - `REQ-1-1-1, REQ-1-2-1, REQ-1-2-2, REQ-1-3-1, REQ-1-3-2`: home list, create page, rename, CSV import/export, editor shell (title, tabs, formula bar, grid display).
2. **REQ-2** - `REQ-2-1-1..4`, `REQ-2-2-1`, `REQ-2-2-2`: worksheet lifecycle and row/column structure.
3. **REQ-3** - `REQ-3-1-1, REQ-3-1-2, REQ-3-1-3, REQ-3-2-1, REQ-3-2-2`: cell/range editing, paste, copy/cut, undo/redo.
4. **REQ-4** - `REQ-4-1-1, REQ-4-1-2, REQ-4-2-1, REQ-4-2-2`: formula engine.
5. **REQ-5-1** - `REQ-5-1-1, REQ-5-1-2`: sort and filter.
6. **REQ-5-2** - `REQ-5-2-1`: data validation.
7. **REQ-5-3** - `REQ-5-3-1`: pivot table.

