export type SessionUser = { username: string; email: string };

export type ApiResult<T> = { ok: boolean; status: number; data: T | null };

export async function apiGet<T>(path: string): Promise<{ status: number; data: T }> {
  const res = await fetch(`/api${path}`, { headers: { Accept: 'application/json' } });
  const data = await res.json().catch(() => null);
  return { status: res.status, data: data as T };
}

export async function apiSend(path: string, method: 'POST'|'PUT'|'DELETE', body?: unknown) {
  const res = await fetch(`/api${path}`, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
    keepalive: true,
  });
  const data = await res.json().catch(() => null);
  return { ok: res.ok, status: res.status, data: (data ?? {}) as any };
}
