router.post('/organizations', requireUser, wrap(async (req, res) => {
  const body = req.body || {};
  const rawName = String(body.name ?? '');
  const normalizedName = normalizeOrganizationName(rawName);
  const displayName = String(body.displayName ?? '');
  const errors = {};
  if (normalizedName && await getOrganization(normalizedName)) errors.name = 'Organization name already exists';
  else if (!isValidOrganizationName(normalizedName)) errors.name = 'Organization name format is invalid';
  if (!isValidDisplayName(displayName)) errors.displayName = 'Display name is required';
  if (Object.keys(errors).length) { res.status(422).json({errors}); return; }
  await withTransaction(async (tx) => {
    const result = await tx.run('INSERT INTO organizations (name, display_name, created_at) VALUES (?,?,?)', [normalizedName, displayName.trim(), now]);
    await tx.run('INSERT INTO organization_members (org_id, account_id, role, created_at) VALUES (?,?,\'Owner\',?)', [result.lastID, req.account.id, now]);
  });
  res.status(201).json({ name: normalizedName });
}));
