async function openManageAccess(page: Page): Promise<void> {
  await signInAs(page, 'repo-admin');
  await page.getByRole('link', { name: 'acme-docs', exact: true }).click();
  await page.getByRole('link', { name: 'Settings', exact: true }).click();
  await page.getByRole('link', { name: 'Manage access', exact: true }).click();
}

test('REQ-2-3 scenario 1: an Admin grants a team Write access that persists', async ({ page }) => {
  await openManageAccess(page);
  await page.getByRole('button', { name: 'Add people or teams', exact: true }).click();

  const dialog = page.getByRole('dialog');
  await dialog.getByLabel('Search', { exact: true }).fill('frontend-team');
  await dialog.getByRole('option', { name: 'frontend-team', exact: true }).click();
  await dialog.getByLabel('Role', { exact: true }).click();
  await dialog.getByRole('option', { name: 'Write', exact: true }).click();
  await dialog.getByRole('button', { name: 'Add', exact: true }).click();

  const row = page.getByRole('row', { name: /frontend-team/ });
  await expect(row).toBeVisible();
  await expect(row.getByText('frontend-team', { exact: true })).toBeVisible();
  await expect(row.getByText('Role: Write', { exact: true })).toBeVisible();

  await page.reload();
  await expect(page.getByText('frontend-team', { exact: true })).toBeVisible();
});

test('REQ-2-3 scenario 2: changing a role updates the existing access row', async ({ page }) => {
  await openManageAccess(page);

  const row = page.getByRole('row', { name: /access-role-team/ });
  await expect(row.getByText('Role: Write', { exact: true })).toBeVisible();

  await row.getByLabel('Role', { exact: true }).selectOption('Read');
  await row.getByRole('button', { name: 'Save', exact: true }).click();

  await page.reload();
  const rows = page.getByRole('row', { name: /access-role-team/ });
  await expect(rows).toHaveCount(1);
  await expect(rows.getByText('Role: Read', { exact: true })).toBeVisible();
});
  await page.getByRole('button', { name: 'Save', exact: true }).click();
  await expect(page.getByText('Cyclic team hierarchy is not allowed', { exact: true })).toBeVisible();

  await page.reload();
  await expect(page.getByLabel('Parent team', { exact: true })).toHaveValue('platform-team');
});

